-- Disposable synthetic affected-schema fixture; no customer data or production connection.
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,email_confirmed_at timestamptz,deleted_at timestamptz);
CREATE TABLE public.profiles(user_id uuid PRIMARY KEY REFERENCES auth.users ON DELETE CASCADE,premium_status boolean,plan_tier text,pro_free_trial_consumed boolean);
CREATE TABLE public.email_preferences(user_id uuid PRIMARY KEY REFERENCES auth.users ON DELETE CASCADE,marketing_emails boolean);
CREATE TABLE public.case_status(id uuid PRIMARY KEY,user_id uuid REFERENCES auth.users ON DELETE CASCADE,current_status text,last_checked_at timestamptz,last_check_failed_at timestamptz);
CREATE TABLE public.email_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users ON DELETE CASCADE,email_address text,email_type text,email_subject text,email_data jsonb,status text,sent_at timestamptz);
CREATE TABLE public.payment_transactions(id uuid DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users ON DELETE CASCADE,status text);
CREATE TABLE public.blocked_emails(id uuid DEFAULT gen_random_uuid(),email text);
CREATE FUNCTION public.test_assert(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION '%',message; END IF; END $$;
CREATE FUNCTION public.test_user(n integer) RETURNS uuid LANGUAGE sql AS $$ SELECT ('10000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid $$;
CREATE FUNCTION public.test_case(n integer) RETURNS uuid LANGUAGE sql AS $$ SELECT ('20000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid $$;
INSERT INTO auth.users SELECT public.test_user(n),'synthetic-'||n||'@example.invalid',now(),null FROM generate_series(1,30) n;
INSERT INTO public.profiles SELECT id,false,'free',false FROM auth.users;
INSERT INTO public.email_preferences SELECT id,true FROM auth.users;
INSERT INTO public.case_status SELECT public.test_case(n),public.test_user(n),'Case Was Received And A Receipt Notice Was Sent',now(),null FROM generate_series(1,30) n;
-- APPLY MIGRATION HERE
SELECT public.test_assert((SELECT count(*) FROM public.pending_case_email_sequences)=0,'migration backfilled customers');
SELECT public.test_assert(NOT has_table_privilege('anon','public.pending_case_email_sequences','SELECT'),'anonymous reads private campaign');
SELECT public.test_assert(NOT has_table_privilege('authenticated','public.pending_case_email_sequences','SELECT'),'customer reads campaign');
SELECT public.test_assert(NOT has_table_privilege('service_role','public.pending_case_email_sequences','UPDATE'),'service has direct state mutations');
SELECT public.test_assert((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='public.pending_case_email_sequences'::regclass),'forced RLS missing');
SELECT public.test_assert(NOT has_function_privilege('authenticated','public.reserve_case_promotion(uuid,text,uuid,text,text)','EXECUTE'),'customer reserves promotions');
SELECT public.test_assert(has_function_privilege('service_role','public.reserve_case_promotion(uuid,text,uuid,text,text)','EXECUTE'),'service cannot reserve promotions');
SELECT public.record_pending_case_email_sequence(public.test_user(1),public.test_case(2));
SELECT public.test_assert((SELECT count(*) FROM public.pending_case_email_sequences)=0,'foreign case enrolled');
UPDATE public.case_status SET last_check_failed_at=now() WHERE id=public.test_case(1);
SELECT public.record_pending_case_email_sequence(public.test_user(1),public.test_case(1));
SELECT public.test_assert((SELECT count(*) FROM public.pending_case_email_sequences)=0,'failed check enrolled');
UPDATE public.case_status SET last_check_failed_at=null,current_status='Request for Evidence Was Sent' WHERE id=public.test_case(1);
SELECT public.record_pending_case_email_sequence(public.test_user(1),public.test_case(1));
SELECT public.test_assert((SELECT count(*) FROM public.pending_case_email_sequences)=0,'action-required case enrolled');
UPDATE public.case_status SET current_status='Case Was Received' WHERE id=public.test_case(1);
SELECT public.record_pending_case_email_sequence(public.test_user(n),public.test_case(n)) FROM generate_series(1,30) n;
SELECT public.test_assert((SELECT count(*) FROM public.pending_case_email_sequences)=30,'valid cases not enrolled');
SELECT public.test_assert(EXISTS (SELECT 1 FROM public.pending_case_email_sequences WHERE arm='holdout'),'holdout absent');
SELECT public.test_assert(NOT EXISTS(SELECT 1 FROM public.pending_case_email_sequences WHERE arm IS DISTINCT FROM CASE WHEN get_byte(sha256(convert_to(user_id::text,'UTF8')),0)%5=0 THEN 'holdout' ELSE 'treatment' END),'assignment not deterministic');
SELECT public.test_assert(NOT EXISTS (SELECT 1 FROM public.list_due_case_promotions()),'email before 24h');
-- Fixture-only aging/assignment makes boundary assertions deterministic.
UPDATE public.pending_case_email_sequences SET first_verified_at=now()-interval '25 hours',arm='treatment';
UPDATE public.pending_case_email_sequences SET arm='holdout' WHERE user_id=public.test_user(3);
UPDATE public.case_status SET current_status='Case Was Approved' WHERE id=public.test_case(4);
UPDATE public.case_status SET last_checked_at=now()-interval '73 hours' WHERE id=public.test_case(5);
UPDATE public.email_preferences SET marketing_emails=false WHERE user_id=public.test_user(6);
SELECT public.test_assert((SELECT unsubscribed_at IS NOT NULL FROM public.pending_case_email_sequences WHERE user_id=public.test_user(6)), 'unsubscribe guardrail missing');
UPDATE public.profiles SET premium_status=true,plan_tier='pro' WHERE user_id=public.test_user(7);
INSERT INTO public.payment_transactions(user_id,status) VALUES(public.test_user(8),'succeeded');
UPDATE public.email_preferences SET marketing_emails=null WHERE user_id=public.test_user(10);
INSERT INTO public.blocked_emails(email) VALUES('synthetic-11@example.invalid');
UPDATE public.profiles SET pro_free_trial_consumed=true WHERE user_id=public.test_user(12);
SELECT public.test_assert(NOT EXISTS(SELECT 1 FROM public.list_due_case_promotions() WHERE user_id IN (SELECT public.test_user(n) FROM generate_series(3,8) n) OR user_id IN (public.test_user(10),public.test_user(11),public.test_user(12))),'ineligible recipient due');
SELECT public.test_assert(public.reserve_case_promotion(public.test_user(1),'pending_case_first',gen_random_uuid(),'test','wrong@example.invalid') IS NULL,'wrong address reserved');
SELECT public.test_assert(public.reserve_case_promotion(public.test_user(1),'pending_case_first',gen_random_uuid(),'test','synthetic-1@example.invalid') IS NOT NULL,'first email not reserved');
SELECT public.test_assert(public.reserve_case_promotion(public.test_user(1),'pending_case_first',gen_random_uuid(),'test','synthetic-1@example.invalid') IS NULL,'duplicate first email');
UPDATE public.email_queue SET status='sent' WHERE user_id=public.test_user(1);
SELECT public.test_assert(NOT public.engage_pending_case_offer(public.test_user(2),(SELECT first_message_id FROM public.pending_case_email_sequences WHERE user_id=public.test_user(1))),'foreign activity recorded');
SELECT public.test_assert(public.engage_pending_case_offer(public.test_user(1),(SELECT first_message_id FROM public.pending_case_email_sequences WHERE user_id=public.test_user(1))),'owner activity not recorded');
SELECT public.test_assert(NOT public.engage_pending_case_offer(public.test_user(1),(SELECT first_message_id FROM public.pending_case_email_sequences WHERE user_id=public.test_user(1))),'repeated activity resets clock');
SELECT public.test_assert(public.reserve_case_promotion(public.test_user(1),'pending_case_followup',gen_random_uuid(),'test','synthetic-1@example.invalid') IS NULL,'followup before 24h');
UPDATE public.pending_case_email_sequences SET engaged_at=now()-interval '25 hours' WHERE user_id=public.test_user(1);
SELECT public.test_assert(public.reserve_case_promotion(public.test_user(1),'pending_case_followup',gen_random_uuid(),'test','synthetic-1@example.invalid') IS NOT NULL,'followup not reserved');
SELECT public.test_assert(public.reserve_case_promotion(public.test_user(1),'checkout_recovery',gen_random_uuid(),'test','synthetic-1@example.invalid') IS NULL,'third promotion reserved');
-- Legacy checkout writer also shares the cap.
INSERT INTO public.email_queue(user_id,email_type,status) VALUES(public.test_user(1),'checkout_recovery','pending');
SELECT public.test_assert((SELECT count(*) FROM public.email_queue WHERE user_id=public.test_user(1))=2,'legacy path bypassed cap');
SELECT public.test_assert(public.reserve_case_promotion(public.test_user(2),'pending_case_first',gen_random_uuid(),'test','synthetic-2@example.invalid') IS NOT NULL,'second first not reserved');
INSERT INTO public.email_queue(user_id,email_type,status) VALUES(public.test_user(2),'checkout_recovery','campaign_unknown');
UPDATE public.email_queue SET status='sent' WHERE user_id=public.test_user(2) AND email_type='pending_case_first';
SELECT public.engage_pending_case_offer(public.test_user(2),(SELECT first_message_id FROM public.pending_case_email_sequences WHERE user_id=public.test_user(2)));
UPDATE public.pending_case_email_sequences SET engaged_at=now()-interval '25 hours' WHERE user_id=public.test_user(2);
SELECT public.test_assert(public.reserve_case_promotion(public.test_user(2),'pending_case_followup',gen_random_uuid(),'test','synthetic-2@example.invalid') IS NULL,'ambiguous recovery did not count');
DELETE FROM public.case_status WHERE id=public.test_case(2);
SELECT public.test_assert((SELECT case_id IS NULL FROM public.pending_case_email_sequences WHERE user_id=public.test_user(2)),'removed case still linked');
SELECT public.test_assert(public.reserve_case_promotion(public.test_user(2),'pending_case_followup',gen_random_uuid(),'test','synthetic-2@example.invalid') IS NULL,'removed case still eligible');
SELECT public.test_assert((SELECT count(*) FROM public.email_queue WHERE user_id=public.test_user(2))=2,'case removal lost unsubscribe mapping');
DELETE FROM auth.users WHERE id=public.test_user(2);
SELECT public.test_assert(NOT EXISTS(SELECT 1 FROM public.pending_case_email_sequences WHERE user_id=public.test_user(2)),'deleted account state retained');
SELECT public.test_assert(NOT EXISTS(SELECT 1 FROM public.email_queue WHERE user_id=public.test_user(2)),'deleted account email retained');
-- Prepare concurrency: one sent first email leaves exactly one promotional slot.
SELECT public.reserve_case_promotion(public.test_user(9),'pending_case_first',gen_random_uuid(),'test','synthetic-9@example.invalid');
UPDATE public.email_queue SET status='sent' WHERE user_id=public.test_user(9);
SELECT public.engage_pending_case_offer(public.test_user(9),(SELECT first_message_id FROM public.pending_case_email_sequences WHERE user_id=public.test_user(9)));
UPDATE public.pending_case_email_sequences SET engaged_at=now()-interval '25 hours' WHERE user_id=public.test_user(9);
